={{ (() => {
  const m = $json.message ?? {};
  const entities = [...(m.entities || []), ...(m.caption_entities || [])];
  const embedded = entities.filter(e => e.type === 'text_link' && e.url).map(e => e.url);
  const candidates = [m.text, m.caption, ...embedded, m.link_preview_options?.url].filter(v => typeof v === 'string');
  const pattern = /(?:https?:\/\/)?(?:www\.)?instagram\.com\/(?:[A-Za-z0-9._]+\/)?p\/[A-Za-z0-9_-]+(?:[^\s<>]*)?/i;
  for (const value of candidates) {
    const match = value.match(pattern);
    if (match) return /^https?:\/\//i.test(match[0]) ? match[0] : 'https://' + match[0];
  }
  throw new Error('Cabang URL ini khusus posting Instagram /p/. Pesan tidak memuat URL yang sesuai.');
})() }}

