return $input.all().map((item, index) => {
  // Baca URL dari struktur input pada screenshot.
  // Field lain disediakan sebagai alternatif.
  const input = [
    item.json.instagram_url,
    item.json.message?.link_preview_options?.url,
    item.json.url,
    item.json.message?.text,
    item.json.message?.caption,
  ].find(value => typeof value === "string" && value.trim());

  if (!input) {
    throw new Error(
      "URL tidak ditemukan. Periksa field input dari node sebelumnya."
    );
  }

  // Mendukung URL dengan username, tanpa username,
  // parameter tambahan, atau URL di dalam teks pesan.
  const match = input.trim().match(
    /https?:\/\/(?:www\.)?instagram\.com\/(?:[A-Za-z0-9._]+\/)?p\/([A-Za-z0-9_-]+)(?=[/?#\s)\]>]|$)/i
  );

  if (!match) {
    throw new Error(
      "Format URL tidak sesuai. Gunakan URL posting Instagram dengan /p/."
    );
  }

  const shortcode = match[1];
  const normalizedUrl =
    `https://www.instagram.com/p/${shortcode}/`;

  return {
    json: {
      ...item.json,
      instagram_url: normalizedUrl,
      url: normalizedUrl,
      shortcode,
    },
    pairedItem: {
      item: index,
    },
  };
});

const expectedItems = $('Normalisasi URL').all();
if (expectedItems.length !== 1) throw new Error('Workflow ini memproses satu URL per pesan. Kirim URL dalam pesan terpisah.');
const expected = expectedItems[0].json.shortcode;
const output = [];
for (const [inputIndex, item] of $input.all().entries()) {
  const post = item.json;
  if (post.error) throw new Error(`Pengambilan posting gagal: ${post.errorDescription || JSON.stringify(post.error)}`);
  const urlCode = String(post.url || '').match(/\/p\/([A-Za-z0-9_-]+)/)?.[1];
  const actual = post.shortCode || urlCode;
  if (!actual || actual !== expected || (urlCode && urlCode !== expected)) {
    throw new Error(`Posting hasil Apify tidak sesuai input. Diminta: ${expected}; diterima: ${actual || 'kode tidak tersedia'}. Jalankan ulang jalur URL dari pesan baru.`);
  }
  const children = Array.isArray(post.childPosts) ? post.childPosts : [];
  let candidates = [];
  if (children.length) {
    candidates = children.map((child, i) => ({url: child.displayUrl, slide: i + 1, isVideo: child.type === 'Video' || Boolean(child.videoUrl)})).filter(child => !child.isVideo);
  } else if (post.type !== 'Video' && !post.videoUrl) {
    const urls = Array.isArray(post.images) && post.images.length ? post.images : [post.displayUrl];
    candidates = urls.map((url, i) => ({url, slide: i + 1}));
  }
  const seen = new Set();
  for (const candidate of candidates) {
    const url = candidate.url;
    if (typeof url !== 'string' || !url.startsWith('https://') || seen.has(url)) continue;
    seen.add(url);
    output.push({
      json: {post_url: post.url || post.inputUrl || '', shortcode: post.shortCode || '', slide: candidate.slide, image_url: url},
      pairedItem: {item: inputIndex}
    });
  }
}
if (!output.length) throw new Error('Tidak ada gambar ditemukan. Periksa output dan log Apify; posting mungkin tidak tersedia atau hanya berupa video.');
return output;

parameters.fileId:
={{ (() => {
  const message = $json.message ?? {};
  const photos = Array.isArray(message.photo) ? message.photo : [];
  const photo = photos.reduce((best, current) =>
    !best || ((current.width || 0) * (current.height || 0) > (best.width || 0) * (best.height || 0)) ? current : best, null);
  const fileId = message.document?.file_id || photo?.file_id || message.video?.file_id || message.audio?.file_id || message.voice?.file_id || message.animation?.file_id || message.video_note?.file_id || message.sticker?.file_id;
  if (!fileId) throw new Error('Tidak ada file_id pada pesan masuk. Kirim lampiran langsung, bukan preview URL.');
  return fileId;
})() }}

